<template>\n  <div class="workmode">\n    <div class="workmode-container">\n      <h1>⚡ Darba režīms</h1>\n      <p class="subtitle">Fokusējies uz VIENU uzdevumu vienlaicīgi</p>\n      \n      <div v-if="currentTask" class="focused-task">\n        <div class="task-content">\n          <h2>{{ currentTask.title }}</h2>\n          <p class="description">{{ currentTask.description }}</p>\n          <div class="priority-display" :class="currentTask.priority">\n            <span>Prioritāte: {{ currentTask.priority }}</span>\n          </div>\n        </div>\n        \n        <div class="workmode-actions">\n          <button @click="completeTask" class="btn btn-complete">✓ Pabeigt uzdevumu</button>\n          <button @click="skipTask" class="btn btn-skip">→ Pāriet uz nākamo</button>\n          <button @click="pauseTask" class="btn btn-pause">⏸ Pauzēt</button>\n        </div>\n        \n        <div class="timer" v-if="sessionActive">\n          <p>Laiks: {{ formatTime(sessionTime) }}</p>\n        </div>\n      </div>\n      \n      <div v-else class="no-tasks">\n        <p>Nav pieejamu uzdevumu. Izveidojiet vienu, lai sāktu fokusēšanos!</p>\n        <router-link to="/dashboard" class="btn btn-primary">Uz paneli</router-link>\n      </div>\n    </div>\n  </div>\n</template>\n\n<script setup>\nimport { ref, onMounted, watch } from 'vue'\nimport { useTasksStore } from '../stores/tasks.js'\nimport axios from 'axios'\n\nconst tasksStore = useTasksStore()\nconst currentTask = ref(null)\nconst sessionActive = ref(false)\nconst sessionTime = ref(0)\n\nonMounted(async () => {\n  await tasksStore.fetchTasks()\n  // Get first task that's not completed or skipped\n  const availableTask = tasksStore.tasks.find(t => t.status === 'todo' || t.status === 'in_progress')\n  if (availableTask) {\n    currentTask.value = availableTask\n    startSession()\n  }\n})\n\nconst startSession = () => {\n  sessionActive.value = true\n  const interval = setInterval(() => {\n    sessionTime.value++\n  }, 1000)\n  \n  watch(() => sessionActive.value, (newVal) => {\n    if (!newVal) clearInterval(interval)\n  })\n}\n\nconst completeTask = async () => {\n  await tasksStore.updateTask(currentTask.value.id, { status: 'completed' })\n  moveToNextTask()\n}\n\nconst skipTask = async () => {\n  await tasksStore.updateTask(currentTask.value.id, { status: 'skipped' })\n  moveToNextTask()\n}\n\nconst pauseTask = () => {\n  sessionActive.value = false\n}\n\nconst moveToNextTask = () => {\n  sessionTime.value = 0\n  const availableTask = tasksStore.tasks.find(t => (t.status === 'todo' || t.status === 'in_progress') && t.id !== currentTask.value.id)\n  if (availableTask) {\n    currentTask.value = availableTask\n    sessionActive.value = true\n  } else {\n    currentTask.value = null\n  }\n}\n\nconst formatTime = (seconds) => {\n  const hrs = Math.floor(seconds / 3600)\n  const mins = Math.floor((seconds % 3600) / 60)\n  const secs = seconds % 60\n  return `${hrs.toString().padStart(2, '0')}:${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`\n}\n</script>\n\n<style scoped>\n.workmode {\n  min-height: 100vh;\n  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  padding: 20px;\n}\n\n.workmode-container {\n  background: white;\n  border-radius: 16px;\n  padding: 40px;\n  max-width: 700px;\n  width: 100%;\n  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.3);\n}\n\nh1 {\n  text-align: center;\n  color: #667eea;\n  font-size: 2.5rem;\n  margin-bottom: 10px;\n}\n\n.subtitle {\n  text-align: center;\n  color: #999;\n  font-size: 1.1rem;\n  margin-bottom: 40px;\n}\n\n.focused-task {\n  text-align: center;\n}\n\n.task-content h2 {\n  font-size: 2rem;\n  color: #333;\n  margin-bottom: 15px;\n}\n\n.description {\n  color: #666;\n  font-size: 1.1rem;\n  margin-bottom: 20px;\n  line-height: 1.6;\n}\n\n.priority-display {\n  display: inline-block;\n  padding: 10px 20px;\n  border-radius: 20px;\n  font-weight: 600;\n  margin-bottom: 30px;\n}\n\n.priority-display.low {\n  background: #c8e6c9;\n  color: #2e7d32;\n}\n\n.priority-display.medium {\n  background: #fff9c4;\n  color: #f57f17;\n}\n\n.priority-display.high {\n  background: #ffcdd2;\n  color: #c62828;\n}\n\n.workmode-actions {\n  display: flex;\n  flex-direction: column;\n  gap: 15px;\n  margin-bottom: 30px;\n}\n\n.btn {\n  padding: 15px 30px;\n  border: none;\n  border-radius: 8px;\n  font-size: 1rem;\n  font-weight: 600;\n  cursor: pointer;\n  transition: all 0.3s;\n}\n\n.btn-complete {\n  background: #4caf50;\n  color: white;\n}\n\n.btn-complete:hover {\n  background: #45a049;\n  transform: translateY(-2px);\n}\n\n.btn-skip {\n  background: #2196f3;\n  color: white;\n}\n\n.btn-skip:hover {\n  background: #0b7dda;\n  transform: translateY(-2px);\n}\n\n.btn-pause {\n  background: #ff9800;\n  color: white;\n}\n\n.btn-pause:hover {\n  background: #e68900;\n  transform: translateY(-2px);\n}\n\n.timer {\n  font-size: 1.5rem;\n  color: #667eea;\n  font-weight: 600;\n}\n\n.no-tasks {\n  text-align: center;\n  color: #999;\n  padding: 40px;\n}\n\n.btn-primary {\n  display: inline-block;\n  padding: 12px 30px;\n  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);\n  color: white;\n  text-decoration: none;\n  border-radius: 8px;\n  margin-top: 20px;\n}\n</style>\n